import { test, expect } from '@playwright/test';

test.describe('Notification Message Rendered Tests', () => {
  test('should display the notification message successfully', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await page.click('a#click-here');
    await expect(page).toHaveURL(/.*notification_message_rendered/);
    await expect(page.locator('#flash')).toBeVisible();
    await expect(page.locator('#flash')).toHaveTextContaining('Action successful');
  });

  test('should not change the URL when clicking the link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await page.click('a#click-here');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/notification_message_rendered');
  });
});
